import {getLanguage} from './i18n.mjs';
import {VERTICALS} from './verticals.mjs';
const vrw=(th,en)=>getLanguage()==='en'?en:th;
const verticalStates=new Map();
export function newVerticalState(key,caseId){const p=VERTICALS[key];if(!p)throw Error('Unknown industry');const c=p.failures.find(x=>x.id===caseId)||p.failures[0];const s={key,caseId:c.id,recovered:false,events:Array.from({length:3},(_,i)=>({id:key.toUpperCase()+'-EVT-'+(i+1),attempts:c.id==='network'?0:1,ack:c.id!=='network'})),ledger:c.id==='network'?[]:[key.toUpperCase()+'-EVT-1',key.toUpperCase()+'-EVT-2',key.toUpperCase()+'-EVT-3'],duplicates:0};return s;}
export function verticalState(key){if(!verticalStates.has(key))verticalStates.set(key,newVerticalState(key));return verticalStates.get(key);}
export function recoverVertical(s){if(s.recovered)return;s.recovered=true;if(s.caseId==='network')for(const [i,e] of s.events.entries()){e.attempts++;if(!s.ledger.includes(e.id))s.ledger.push(e.id);else s.duplicates++;e.ack=i!==0;}}
export function replayVertical(s){if(!s.recovered)return;const pending=s.events.filter(e=>!e.ack),list=pending.length?pending:s.events.slice(0,1);for(const e of list){e.attempts++;if(s.ledger.includes(e.id))s.duplicates++;else s.ledger.push(e.id);e.ack=true;}}
export function verticalMetrics(s){const p=VERTICALS[s.key],c=p.failures.find(x=>x.id===s.caseId),delivered=s.recovered?c.completed:(s.key==='retail'?c.completed:0),dataPending=s.events.filter(e=>!e.ack).length,workPending=s.recovered?(s.key==='factory'?4-c.completed:0):4-delivered,wait=s.recovered?7:c.wait;return{delivered,revenue:delivered*p.price,cost:delivered*p.cost,extra:c.extra,profit:delivered*(p.price-p.cost)-c.extra,dataPending,workPending,wait,unique:s.ledger.length};}
export function verticalVisual(key){const s=verticalState(key),p=VERTICALS[key],c=p.failures.find(x=>x.id===s.caseId),m=verticalMetrics(s);return{haltCloud:!s.recovered&&c.id==='network',blockNode:!s.recovered&&c.id!=='network'?c.node:null,bufferNode:c.node,pending:m.dataPending+m.workPending};}
export function renderVerticalQuick(key){const p=VERTICALS[key],s=verticalState(key),m=verticalMetrics(s);return `<section class="panel resilience-quick"><div class="resilience-controls"><label for="vertical-case">${vrw('เหตุขัดข้องเฉพาะธุรกิจ','Industry-specific failure')}</label><select id="vertical-case">${p.failures.map(c=>`<option value="${c.id}" ${c.id===s.caseId?'selected':''}>${vrw(c.th,c.en)}</option>`).join('')}</select><button id="vertical-recover" class="button button-primary" ${s.recovered?'disabled':''}>${vrw('จำลองกู้คืนตาม SOP','Simulate approved recovery')}</button><button id="vertical-replay" class="button button-white" ${!s.recovered?'disabled':''}>${vrw('ส่งรหัสเดิมซ้ำ','Replay same IDs')}</button><button id="vertical-reset" class="button button-white">${vrw('เริ่มสถานการณ์ใหม่','Restart scenario')}</button><button id="vertical-details" class="button button-white">${vrw('เปรียบเทียบผลและขั้นตอนพนักงาน','Compare outcomes and staff actions')}</button><p>${vrw('ข้อมูลรอ ACK','Unacknowledged events')}: ${m.dataPending} · ${vrw('งานปฏิบัติการที่พัก','Held operational work')}: ${m.workPending} · ${vrw('เหตุการณ์กลางไม่ซ้ำ','Unique central events')}: ${m.unique} · ${vrw('ตัดข้อความซ้ำ','Duplicates suppressed')}: ${s.duplicates}</p></div></section>`;}
export function renderVerticalRecovery(key){const p=VERTICALS[key],s=verticalState(key),c=p.failures.find(x=>x.id===s.caseId),during=verticalMetrics(newVerticalState(key,c.id)),future=structuredClone(s);recoverVertical(future);const after=verticalMetrics(future),baseline={delivered:4,revenue:4*p.price,profit:4*(p.price-p.cost),dataPending:0,workPending:0,wait:4,unique:3},now=verticalMetrics(s),money=n=>'฿'+new Intl.NumberFormat(getLanguage()==='en'?'en-GB':'th-TH').format(n);return `<section class="panel activity vertical-recovery" id="vertical-recovery"><div class="panel-header"><h2>${vrw('ผลต่อธุรกิจและวิธีรับมือ','Business impacts and response')}</h2><span class="tiny-tag">${vrw(c.th,c.en)}</span></div><div class="failure-dashboard"><p><strong>${vrw(c.thQueue,c.enQueue)}</strong></p><p>${vrw('สถานการณ์และตัวเลขเป็นสมมติ เปรียบเทียบโอกาสงาน 4 หน่วยเท่ากัน ไม่ใช่สามช่วงเวลาที่บวกเข้าด้วยกัน คิวนี้อยู่ในหน่วยความจำตัวอย่าง ไม่ใช่ระบบเก็บถาวรจริง','Synthetic assumptions compare 4 equal work opportunities, not additive time windows. This demonstration queue is in memory, not a production durable store.')}</p><div class="failure-stages">${[[vrw('ก่อนขัดข้อง','Before failure'),baseline,vrw('ฐานสมมติปกติ','Assumed normal baseline')],[vrw('ระหว่างขัดข้อง','During failure'),during,vrw('ภาพเมื่อเริ่มเหตุ','Initial failure snapshot')],[vrw('หลังกู้คืน','After recovery'),s.recovered?now:after,s.recovered?vrw('สถานะจำลองที่กดแล้ว','Your simulated state'):vrw('คาดการณ์ ยังไม่กดกู้คืน','Projected; recovery not triggered')]].map(([title,m,note])=>`<article class="failure-stage"><h4>${title}</h4><p class="stage-note">${note}</p><dl><dt>${vrw('งานส่งมอบ','Delivered work')}</dt><dd>${m.delivered}/4</dd><dt>${vrw('รายได้งานส่งมอบ','Delivered revenue')}</dt><dd>${money(m.revenue)}</dd><dt>${vrw('ส่วนเกินหลังค่าใช้จ่ายเพิ่ม','Contribution after extra costs')}</dt><dd>${money(m.profit)}</dd><dt>${vrw('เวลารอเฉลี่ย','Average wait')}</dt><dd>${m.wait} ${vrw('นาที','min')}</dd><dt>${vrw('ข้อมูลรอ ACK','Unacknowledged events')}</dt><dd>${m.dataPending}</dd><dt>${vrw('งานพักปฏิบัติการ','Held operational work')}</dt><dd>${m.workPending}</dd></dl></article>`).join('')}</div>
 <div class="failure-actions ${now.workPending||now.wait>10?'red':now.dataPending?'amber':'green'}"><h3>${vrw('พนักงานควรทำอะไรต่อ','What staff should do next')}</h3><p>${vrw(c.thAction,c.enAction)}</p><p>${!s.recovered?vrw('ยังขัดข้อง: เก็บเลขงานเดิมและหลักฐาน หัวหน้ากะอนุมัติวิธีสำรองตาม SOP ก่อนรับงานต่อ','Failure active: preserve work references and evidence. The shift lead approves fallback SOPs before accepting more work.'):now.dataPending?vrw('กู้คืนแล้วแต่ ACK ยังไม่ครบ: ส่งรหัสเดิมซ้ำและทวนจำนวนเหตุการณ์กลาง ห้ามสร้างยอดใหม่','Recovered but ACK is missing: replay original IDs and reconcile unique central events; do not create replacement business activity.'):now.workPending?vrw('ข้อมูลส่งครบ แต่ยังมีงานหรือ QC ที่พัก: ยังไม่ถือว่ากลับปกติ ให้เจ้าของงานตรวจรับก่อนส่งมอบ','Data is synchronized, but operational/QC work remains held. Do not call the operation normal; the responsible owner must accept work before dispatch.'):vrw('คิวตัวอย่างเคลียร์แล้ว: ทวนยอด ต้นทุน และหลักฐานส่งมอบก่อนปิดเหตุและติดตามช่วงถัดไป','Sample queues are clear: reconcile value, costs and handover evidence before closing the incident and monitoring the next window.')}</p><ul><li>${vrw('ข้อมูลค้างต้องเป็นศูนย์','Unacknowledged data must be zero')}: ${now.dataPending}</li><li>${vrw('งานพักต้องตรวจรับก่อนปิดเหตุ','Held work needs acceptance before incident closure')}: ${now.workPending}</li><li>${vrw('เกณฑ์เวลารอสาธิต ≤ 10 นาที','Illustrative wait guardrail ≤10 min')}: ${now.wait<=10?vrw('ผ่าน','Pass'):vrw('ไม่ผ่าน','Fail')}</li></ul><p>${vrw('เกณฑ์และราคานี้เป็นตัวอย่าง ต้องปรับตามหน่วยงานจริง ไม่ใช่การรับรองความปลอดภัยหรือสิทธิ์สั่งงานเครื่องจักร','Thresholds and prices are illustrative and require local definition. They do not authorize machine operation or certify safety.')}</p></div>
 <div class="resilience-table"><table class="insight-table"><thead><tr><th>Event ID</th><th>${vrw('ส่งแล้ว','Attempts')}</th><th>ACK</th></tr></thead><tbody>${s.events.map(e=>`<tr><td>${e.id}</td><td>${e.attempts}</td><td>${e.ack?'✓':'—'}</td></tr>`).join('')}</tbody></table></div><p>${vrw('เหตุการณ์กลางไม่ซ้ำ','Unique central events')}: <strong id="vertical-unique">${now.unique}</strong> · ${vrw('ข้อความซ้ำถูกตัด','Duplicates suppressed')}: ${s.duplicates}</p>
 <p>${vrw('เหตุการณ์ยืนยัน 3 รายการเป็นข้อมูลธุรกรรมหรือสถานะ ไม่ใช่นับว่าเกิดยอดขาย 3 ครั้ง การส่งซ้ำใช้รหัสเดิมและไม่เพิ่มผลผลิต ยอดขาย หรือใบงานใหม่','The 3 central events are transaction/status records, not 3 additional sales. Same-ID replay does not add production, sales or jobs.')}</p><p>${vrw('สมมติราคาต่องาน','Assumed price per work unit')} ${money(p.price)} − ${vrw('ต้นทุนผันแปร','variable cost')} ${money(p.cost)}; ${vrw('ค่าแรง/แก้ไข/ของเสียเพิ่ม','extra labor / repair / waste')} ${money(c.extra)}. ${key==='factory'?vrw('งานผลิตที่ยังไม่ผ่าน QC หรือส่งมอบไม่นับเป็นรายได้ งานที่เหลือเป็นงานพัก ไม่จำเป็นต้องเป็นยอดขายที่สูญเสีย','Work not accepted by QC or dispatched is not revenue; remaining work is held, not necessarily lost sales.'):vrw('โอกาสงานที่ไม่สำเร็จในกรณีนี้ไม่คิดเป็นรายได้ เน็ตกลับไม่ได้ลบค่าแก้ไขหรือดึงลูกค้าที่เลิกใช้บริการกลับมา','Uncompleted opportunities do not count as revenue. Recovery does not erase costs or recreate abandoned demand.')}</p><p>${vrw('นี่เป็นส่วนเกินจากสมมติฐาน ไม่ใช่กำไรสุทธิหรือผล A/B ที่พิสูจน์แล้ว','This is assumed contribution, not net accounting profit or proven A/B impact.')}</p></div></section>`;}
export function mountVerticalRecovery(root,key,rerender,onScenario){root.querySelector('#vertical-case').addEventListener('change',e=>{verticalStates.set(key,newVerticalState(key,e.target.value));onScenario(VERTICALS[key].failures.find(c=>c.id===e.target.value).event);rerender();});root.querySelector('#vertical-recover').addEventListener('click',()=>{recoverVertical(verticalState(key));rerender();});root.querySelector('#vertical-replay').addEventListener('click',()=>{replayVertical(verticalState(key));rerender();});root.querySelector('#vertical-reset').addEventListener('click',()=>{verticalStates.set(key,newVerticalState(key,verticalState(key).caseId));rerender();});root.querySelector('#vertical-details').addEventListener('click',()=>root.querySelector('#vertical-recovery').scrollIntoView({behavior:'auto',block:'start'}));}
